using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Demo6.Game;using Demo6.Core.Loot;
public static class GearV3Import {
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play");AssetDatabase.Refresh();foreach(var b in GearBaseTable.All){string p="Assets/Resources/UI/Items/"+b.Id+".png";var t=AssetImporter.GetAtPath(p) as TextureImporter;if(!t)throw new Exception("Missing "+p);t.textureType=TextureImporterType.Default;t.alphaIsTransparency=true;t.mipmapEnabled=false;t.filterMode=FilterMode.Bilinear;t.wrapMode=TextureWrapMode.Clamp;t.textureCompression=TextureImporterCompression.Uncompressed;t.maxTextureSize=1024;t.SaveAndReimport();}
 var art=AssetDatabase.LoadAssetAtPath<CombatArtSet>("Assets/Data/Combat/CombatArtSet.asset");var pArt=art.topDown.player;var sprites=pArt.armors.SelectMany(a=>new[]{a.body,a.sleeve}).Concat(pArt.helms.Select(h=>h.sprite)).Concat(pArt.gloves.SelectMany(g=>new[]{g.fistClosed,g.fistOpen})).Concat(pArt.boots.Select(b=>b.boot)).ToArray();
 var result=new{gearIcons=GearBaseTable.All.Select(b=>new{id=b.Id,path=AssetDatabase.GetAssetPath(Resources.Load<Texture2D>("UI/Items/"+b.Id)),exists=Resources.Load<Texture2D>("UI/Items/"+b.Id)!=null}).ToArray(),heroParts=sprites.Select(s=>new{name=s.name,path=AssetDatabase.GetAssetPath(s),ppu=s.pixelsPerUnit,pivot=s.pivot.ToString(),rect=s.rect.ToString(),bounds=s.bounds.size.ToString()}).ToArray(),armorCount=pArt.armors.Length,helmCount=pArt.helms.Length,glovesCount=pArt.gloves.Length,bootsCount=pArt.boots.Length,ratPreserved=art.topDown.rat.body!=null};File.WriteAllText("아트/장비-UI-v3/검수/import-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
